private String normalizeDots(String host) {
    if (host.indexOf('.') == -1) {
        return host;
    }
    int start = 0, end = host.length();
    boolean changed = false;

    // Correcting the loop condition for leading dots
    while (start < end && host.charAt(start) == '.') {
        start++;
        changed = true;
    }

    // Correcting the loop condition for trailing dots
    while (start < end && host.charAt(end - 1) == '.') {
